// optimization sketch for: Self-Optimizing Mechanism Generator
let s = 65301976;
const rnd = () => (s = (s * 1664525 + 1013904223) >>> 0) / 4294967296;
const target = [1.754, 3.744];
let best = [rnd() * 10, rnd() * 10];
const f = p => -((p[0] - target[0]) ** 2 + (p[1] - target[1]) ** 2);
let bv = f(best);
for (let i = 0; i < 300; i++) {
  const c = [best[0] + (rnd() - 0.5) * 1.6, best[1] + (rnd() - 0.5) * 1.6];
  const cv = f(c); if (cv > bv) { bv = cv; best = c; }
}
console.log(JSON.stringify({ target: target, best: best.map(v => +v.toFixed(3)),
  score: +bv.toFixed(4), iterations: 300 }));

